    const continuousDrop = isTestFieldV2 && isTestFieldMiddlePocket && v2.continuousMiddlePocketDrop;
    const useIncomingPocketAngle = isTestFieldMiddlePocket && !skipPocketAngleCheck && !continuousDrop;
